package com.skbprofitracker.items

import com.google.gson.JsonParser
import com.skbprofitracker.SkbMod

/**
 * Display name -> price key table.
 *
 * Identification is name based on purpose: Hypixel keeps the hover name stable
 * where NBT ids are shared between many items (every attribute shard is
 * `ATTRIBUTE_SHARD`), so the display name plus an explicit table is the only
 * scheme that keeps shards apart. The table is generated by
 * `tools/gen_item_table.py` and shipped as a resource so it can be refreshed
 * without touching code.
 */
object ItemTable {
    data class Entry(
        val name: String,
        val key: String,
        val compactsFrom: String? = null,
        val compactRatio: Int = 0,
        /** Leading colour codes, e.g. "§6", taken from the NEU display name. */
        val color: String? = null,
        /** NPC sell price from the Hypixel item resource; the floor for every other price. */
        val npcPrice: Double? = null,
    )

    private var byName: Map<String, Entry> = emptyMap()
    private var byKey: Map<String, Entry> = emptyMap()
    private var byBaseName: Map<String, Set<String>> = emptyMap()

    /** `Enchanted Book (Smite VI)` also shows up in chat as `Enchanted Book (Smite 6)`. */
    private val BOOK_NAME = Regex("^(Enchanted Book \\(.+?) (I|II|III|IV|V|VI|VII|VIII|IX|X)\\)$")
    private val ROMAN = listOf("I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X")

    /** `[Lvl 1] Ghoul (LEGENDARY)` -> `Ghoul`, the name chat uses when the pet is traded. */
    private val PET_NAME = Regex("^\\[Lvl \\d+] (.+?) \\(([^)]+)\\)$")

    /** Decorative glyphs (`✦`, `☠`, ...) some items carry in front of their name. */
    private val LEADING_GLYPH = Regex("^[^\\p{L}\\p{N}\\[(]+")

    val size: Int get() = byName.size

    fun init() {
        val stream = ItemTable::class.java.getResourceAsStream("/assets/skbprofitracker/items.json")
        if (stream == null) {
            SkbMod.LOGGER.error("items.json is missing from the jar, no item will be tracked")
            return
        }

        val root = stream.use { JsonParser.parseReader(it.reader()).asJsonObject }
        val entries = root.getAsJsonArray("items") ?: return

        val map = HashMap<String, Entry>(entries.size() * 2)
        for (element in entries) {
            val obj = element.asJsonObject
            val entry = Entry(
                name = obj.get("name").asString,
                key = obj.get("key").asString,
                compactsFrom = obj.get("compactsFrom")?.takeIf { !it.isJsonNull }?.asString,
                compactRatio = obj.get("compactRatio")?.takeIf { !it.isJsonNull }?.asInt ?: 0,
                color = obj.get("color")?.takeIf { !it.isJsonNull }?.asString,
                npcPrice = obj.get("npc")?.takeIf { !it.isJsonNull }?.asDouble,
            )
            map[entry.name] = entry
            bookAlias(entry.name)?.let { alias -> map.putIfAbsent(alias, entry) }
        }

        byName = map
        byKey = map.values.associateBy { it.key }
        byBaseName = map.values
            .groupBy { baseName(it.name) }
            .mapValues { (_, entries) -> entries.map { it.key }.toSet() }
        SkbMod.LOGGER.info("Loaded ${map.size} tracked items")
    }

    private fun bookAlias(name: String): String? {
        val match = BOOK_NAME.matchEntire(name) ?: return null
        val level = ROMAN.indexOf(match.groupValues[2]) + 1
        if (level <= 0) return null
        return "${match.groupValues[1]} $level)"
    }

    private fun baseName(name: String): String =
        PET_NAME.matchEntire(name)?.groupValues?.get(1) ?: name

    /**
     * Keys a chat name can refer to.
     *
     * Chat and inventory spell the same item differently: a traded pet is `Ghoul` in chat but
     * `[Lvl 1] Ghoul (LEGENDARY)` in the inventory, and runes carry a glyph in front. Anything
     * the table does not know returns an empty set, which is correct: unknown items are never
     * scored, so they do not need to be fenced off either.
     */
    fun getChatKeys(rawName: String): Set<String> {
        val cleaned = rawName.replace(Regex("§."), "").trim()
        byName[cleaned]?.let { return setOf(it.key) }

        val stripped = cleaned.replace(LEADING_GLYPH, "").trim()
        byName[stripped]?.let { return setOf(it.key) }
        byBaseName[stripped]?.let { return it }

        return emptySet()
    }

    fun get(displayName: String): Entry? = byName[displayName]

    fun getByKey(key: String): Entry? = byKey[key]

    fun isTracked(displayName: String): Boolean = byName.containsKey(displayName)
}
